import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { loadQuestionsFromFile } from "../src/data/nodeQuestionLoader.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const CSV_PATH = path.resolve(__dirname, "../data/questions/takamiya-typing-game-master-v3.csv");
const OUTPUT_PATH = path.resolve(__dirname, "../src/data/defaultQuestions.js");

export function generateBundle() {
  console.log(`Reading Question Master SSOT from: ${CSV_PATH}`);
  const questions = loadQuestionsFromFile(CSV_PATH);
  console.log(`Loaded ${questions.length} questions. Generating bundle at: ${OUTPUT_PATH}`);

  const banner = `/**
 * AUTOGENERATED RUNTIME BUNDLE — DO NOT EDIT MANUALLY
 * Source SSOT: data/questions/takamiya-typing-game-master-v3.csv
 * Generator: scripts/generateQuestionBundle.js
 * Generated at: ${new Date().toISOString()}
 */
`;
  const code = `${banner}export const DEFAULT_QUESTIONS = ${JSON.stringify(questions, null, 2)};\n`;

  fs.writeFileSync(OUTPUT_PATH, code, "utf-8");
  console.log(`✅ Successfully generated defaultQuestions.js with ${questions.length} items.`);
  return questions;
}

// Run directly if called as script
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  generateBundle();
}
